const rows = Array.isArray(msg.payload) ? msg.payload : [];
msg.payload = {
    success: true,
    timestamp: new Date().toISOString(),
    data: rows.map((r, idx) => ({
        rank: idx + 1,
        technician_id: r.id || 'T' + (idx + 1),
        name: r.name || 'UNKNOWN',
        quality_score: Number(r.quality) || 0,
        interventions: Number(r.total) || 0,
        tech_failures: Number(r.failures) || 0,
        escalations: Number(r.escalations) || 0,
        status: 'Available'
    }))
};
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
return msg;

const row = Array.isArray(msg.payload) && msg.payload.length ? msg.payload[0] : null;
if (!row) {
    msg.statusCode = 404;
    msg.payload = { success: false, error: 'Technician not found' };
} else {
    const total = Number(row.total || 0);
    const failures = Number(row.failures || 0);
    const escalations = Number(row.escalations || 0);
    let quality = total > 0 ? Math.round(((total - failures - escalations) / total) * 100) : 0;
    if (quality < 0) quality = 0;
    if (quality > 100) quality = 100;
    let status = 'Available';
    if (quality < 50) status = 'Training';
    else if (quality < 80) status = 'Warning';
    msg.payload = {
        success: true,
        timestamp: new Date().toISOString(),
        data: {
            id: row.id,
            name: row.name,
            role: 'Technician',
            rfid_uid: row.id,
            qr_uid: row.id,
            status: status,
            quality_score: quality,
            interventions_count: total,
            escalations_count: escalations,
            successful_repairs: total - failures - escalations,
            avatar: '👤'
        }
    };
}
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
};
return msg;

msg.topic = `SELECT * FROM machine_daily_history ORDER BY ts DESC LIMIT 100`;
msg.payload = [];
msg.reportType = 'daily';
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const counts = {
    failures: rows.filter(r => r.state === 'FAILURE').length,
    repairs: rows.filter(r => r.action === 'maintenance_end').length,
    escalations: rows.filter(r => r.state === 'ESCALATION').length,
    maintenance: rows.filter(r => r.action === 'maintenance_start').length,
    critical: rows.filter(r => r.state === 'CRITICAL').length
};
msg.payload = {
    success: true,
    timestamp: new Date().toISOString(),
    data: {
        title: msg.reportType === 'daily' ? 'Daily Report' : 'Weekly Report',
        period: new Date().toISOString().split('T')[0],
        totalRows: rows.length,
        counts: counts,
        rows: rows
    }
};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,PUT,DELETE,OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
    "Access-Control-Max-Age": "86400"
};
return msg;
